# Carne module registry: `require("std/<name>")` with lazy install.
#
# This module holds the registry only — it deliberately does NOT import
# the std implementations, so tests pay only for the modules they use.
# Adding a stdlib = one file under std/ exposing
# `install*(ctx: JSContextRef; rt: Runtime): JSObjectRef`
# (generated by the `init` macro in bridge), plus one `registerStd`
# line in ./std/all.nim (binary) or in the tests that need it.
#
# Runtime teardown calls each onTeardown hook in order (std/http and
# std/ws append theirs on import); empty means nothing to clean up.

import std/tables
import std/strutils

import javascriptcore

import ./bridge

type
  Installer* = proc(ctx: JSContextRef; rt: Runtime): JSObjectRef
  PkgRequireHook* = proc(ctx: JSContextRef; spec: string;
    exception: ptr JSValueRef): JSValueRef {.closure.}

var installers = initTable[string, Installer]()

var pkgRequireHook*: PkgRequireHook = nil
  ## File-backed `require("pkg/...")` and relative requires go through
  ## this hook (set by pkg/loader). Nil in tests that do not need it.

var onTeardown*: seq[proc()] = @[]

proc registerStd*(name: string; installer: Installer) =
  ## Registers one stdlib implementation. Called once per module from
  ## std/all.nim (binary) or from individual tests.
  installers[name] = installer

proc requireImpl(ctx: JSContextRef; function, thisObject: JSObjectRef;
    argumentCount: csize_t; arguments: ptr JSValueRef;
    exception: ptr JSValueRef): JSValueRef {.cdecl.} =
  ## Implements global require(spec).
  if not checkArity(argumentCount, 1, 1, "require", ctx, exception):
    return nil
  let args = cast[ptr UncheckedArray[JSValueRef]](arguments)
  var spec: string
  if not strArg(ctx, args, 0, "require", exception, spec):
    return nil
  let rt = currentRt()
  if rt.instances.hasKey(spec):
    return rt.instances[spec]
  if spec.startsWith("pkg/") or spec.startsWith("./") or
      spec.startsWith("../") or spec == "." or spec == "..":
    if pkgRequireHook == nil:
      throwError(ctx, "require: package imports need pkg/loader (" & spec & ")",
        exception)
      return nil
    return pkgRequireHook(ctx, spec, exception)
  if not installers.hasKey(spec):
    throwError(ctx, "require: unknown module \"" & spec & "\"", exception)
    return nil
  let ns = installers[spec](ctx, rt)
  if ns == nil:
    throwError(ctx, "require: failed to initialize \"" & spec & "\"",
      exception)
    return nil
  rt.instances[spec] = ns
  ns

proc installRequire*(rt: Runtime; setupEx: ptr JSValueRef) =
  ## Installs the global require function.
  let global = JSContextGetGlobalObject(rt.ctx)
  setProp(rt.ctx, global, "require",
    makeFunction(rt.ctx, "require", requireImpl), setupEx)
